#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

using ll = long long;

vector<int> digits;
ll memo[20][2][11][10];

ll solve(int pos, bool started, int first, int last, bool tight) {
    if (pos == static_cast<int>(digits.size()))
        return !started || first == last;

    if (!tight) {
        ll &res = memo[pos][started][first][last];
        if (res != -1) return res;
    }

    int limit = tight ? digits[pos] : 9;
    ll result = 0;

    for (int d = 0; d <= limit; ++d) {
        bool nextTight = tight && (d == limit);

        if (!started && d == 0)
            result += solve(pos + 1, false, 10, 0, nextTight);
        else if (!started)
            result += solve(pos + 1, true, d, d, nextTight);
        else
            result += solve(pos + 1, true, first, d, nextTight);
    }

    if (!tight)
        memo[pos][started][first][last] = result;

    return result;
}

ll countUpTo(ll n) {
    if (n < 0) return 0;

    digits.clear();
    string s = to_string(n);
    for (char c : s) digits.push_back(c - '0');

    memset(memo, -1, sizeof(memo));
    return solve(0, false, 10, 0, true);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, r;
    cin >> l >> r;

    if (l > r) {
        cout << 0;
    } else {
        cout << countUpTo(r) - (l > 0 ? countUpTo(l - 1) : 0);
    }

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

using ll = long long;

ll countUpTo(ll n) {
    if (n < 0) return 0;
    if (n < 10) return n + 1;

    int digits = to_string(n).size();
    ll ans = 10;
    ll power = 1;

    for (int len = 2; len < digits; ++len) {
        ans += 9 * power;
        power *= 10;
    }

    ll prefix = n / 10;
    ll firstDigit = n / (power * 10);

    ans += prefix - power;
    if (n % 10 >= firstDigit) ++ans;

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, r;
    cin >> l >> r;

    if (l > r) swap(l, r);

    cout << countUpTo(r) - (l == 0 ? 0 : countUpTo(l - 1));
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll countUpTo(ll n) {
    if (n < 0) return 0;

    ll result = min(n, 9LL) + 1;
    i128 place = 10;

    for (int len = 2; len <= 19; ++len) {
        i128 middleCount = place / 10;

        for (int first = 1; first <= 9; ++first) {
            i128 base = (i128)first * place + first;
            if (base > n) continue;

            i128 maxMiddle = min(middleCount - 1, ((i128)n - base) / 10);
            result += (ll)(maxMiddle + 1);
        }

        place *= 10;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, r;
    cin >> l >> r;

    cout << countUpTo(r) - countUpTo(l - 1);
    return 0;
}

#include <iostream>
#include <string>
#include <climits>
#include <algorithm>
using namespace std;

using ll = long long;

ll countUpTo(ll n) {
    if (n < 0) return 0;

    string s = to_string(n);
    int digits = s.size();

    if (digits == 1) return n + 1;

    ll count = 10;
    ll power = 1;

    for (int length = 2; length < digits; ++length) {
        count += 9 * power;
        power *= 10;
    }

    int first = s.front() - '0';
    int last = s.back() - '0';

    ll middle = 0;
    for (int i = 1; i < digits - 1; ++i)
        middle = middle * 10 + (s[i] - '0');

    count += (first - 1) * power;
    count += middle;
    if (last >= first) ++count;

    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, r;
    cin >> l >> r;

    if (l > r) swap(l, r);

    cout << countUpTo(r) - (l == LLONG_MIN ? 0 : countUpTo(l - 1));
    return 0;
}

#include <iostream>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 countValid(int64 n) {
    if (n < 0) return 0;
    if (n < 10) return n + 1;

    int digits = 0;
    int64 temp = n;
    while (temp > 0) {
        ++digits;
        temp /= 10;
    }

    int64 result = 10;
    int64 power = 1;

    for (int length = 2; length < digits; ++length) {
        result += 9 * power;
        power *= 10;
    }

    int64 firstPower = power * 10;
    int64 firstDigit = n / firstPower;
    int64 middle = (n / 10) % power;

    result += (firstDigit - 1) * power + middle;

    i128 candidate = static_cast<i128>(firstDigit) * firstPower
                   + static_cast<i128>(middle) * 10
                   + firstDigit;

    if (candidate <= n) ++result;

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 l, r;
    cin >> l >> r;

    cout << countValid(r) - (l <= 0 ? 0 : countValid(l - 1));
    return 0;
}

